<?php use AlbaTech\Core\View; $project=$project??[];
$linesFromJson = static function ($raw): string { if (!is_string($raw) || trim($raw) === '') return ''; $decoded = json_decode($raw, true); return is_array($decoded) ? implode("\n", array_map('strval', $decoded)) : ''; };
$featuresText = trim((string)($project['features'] ?? '')) ?: $linesFromJson($project['features_json'] ?? '');
$stackText = trim((string)($project['stack'] ?? '')) ?: $linesFromJson($project['stack_json'] ?? '');
$galleryText = trim((string)($project['gallery'] ?? '')) ?: $linesFromJson($project['gallery_json'] ?? '');
?>
